"use client";
/* Egg, from the Piixpal shadcn registry. Options: https://piixpal.vercel.app/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Egg(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("egg"); }, []);
  return React.createElement("piix-sprite", { "name": "egg", ...piixAttrs(props) });
}

export default Egg;
